from __future__ import annotations

from pydantic import Field
from typing_extensions import NotRequired, TypedDict

from ..core import UNSET, Optional, SdkBaseModel
from .fraud_check_result_wrapper import FraudCheckResultWrapper, FraudCheckResultWrapperDict


class FraudResult2(SdkBaseModel):
    """The fraud result properties of the payment."""

    account_score: int = Field(alias="accountScore")
    """The total fraud score generated by the risk checks."""

    results: Optional[list[FraudCheckResultWrapper]] = UNSET
    """The result of the individual risk checks."""


class FraudResult2Dict(TypedDict):
    account_score: int
    results: NotRequired[list[FraudCheckResultWrapperDict]]
